function addAsText(a: string, b: string): string {
  const n = Math.max(a.length, b.length);
  a = a.padStart(n, "0");
  b = b.padStart(n, "0");
  const out: number[] = [];
  let carry = 0;
  for (let k = n - 1; k >= 0; k--) {
    const sum = a.charCodeAt(k) - 48 + (b.charCodeAt(k) - 48) + carry;
    out.push(sum % 10);
    carry = sum >= 10 ? 1 : 0;
  }
  if (carry) out.push(1);
  return out.reverse().join("");
}

