class Solution:
    def addAsText(self, a: str, b: str) -> str:
        n = max(len(a), len(b))
        a, b = a.zfill(n), b.zfill(n)
        out, carry = [], 0
        for k in range(n - 1, -1, -1):
            s = int(a[k]) + int(b[k]) + carry
            out.append(str(s % 10))
            carry = s // 10
        if carry:
            out.append("1")
        return "".join(reversed(out))

