function addAsText(a: string, b: string): string {
  let i = a.length - 1, j = b.length - 1, carry = 0;
  const out: number[] = [];
  while (i >= 0 || j >= 0 || carry) {
    const sum = (i >= 0 ? a.charCodeAt(i--) - 48 : 0) + (j >= 0 ? b.charCodeAt(j--) - 48 : 0) + carry;
    out.push(sum % 10);
    carry = Math.floor(sum / 10);
  }
  return out.reverse().join("");
}

